from functools import lru_cache
G=['.##.##.','######.','.##.#..','..###..','.......','.......','.......']
cells={(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x=='#'}
# tiles: square color1, Ls mapping by missing corner UL->2 LL->3 UR->4 LR->5
shapes=[]
for r in range(7):
 for c in range(7):
  block={(r+i,c+j) for i in range(2) for j in range(2)}
  if block<=cells: shapes.append((block,1))
  for missing, col in [((0,0),2),((1,0),3),((0,1),4),((1,1),5)]:
   sh=block-{(r+missing[0],c+missing[1])}
   if sh<=cells: shapes.append((sh,col))
by={x:[] for x in cells}
for t in shapes:
 for x in t[0]: by[x].append(t)
sol=[]
def rec(rem,chosen):
 if not rem:
  sol.append(chosen);return
 x=min(rem)
 for t in by[x]:
  if t[0]<=rem: rec(rem-t[0],chosen+[t])
rec(cells,[])
print('cells',len(cells),'solutions',len(sol))
for n,s in enumerate(sol[:20]):
 out=[['.' for _ in range(7)] for _ in range(7)]
 for sh,col in s:
  for r,c in sh: out[r][c]=str(col)
 print(n,[(col,sorted(sh)) for sh,col in s]);print('\n'.join(''.join(x) for x in out))
